ext('c12_eng_ch18',[
C("🐈","कविता का रूप और पृष्ठभूमि",["बच्चों के लिए हास्य कविताएँ","ओल्ड पोसम्स बुक ऑफ़ प्रैक्टिकल कैट्स","1939 में प्रकाशित","बाद में म्यूज़िकल कैट्स बना"],"मैकेविटी द मिस्ट्री कैट टी एस एलियट की एक हास्य कविता है। यह उनके बिल्लियों वाले संग्रह ओल्ड पोसम्स बुक ऑफ़ प्रैक्टिकल कैट्स से ली गई है, जो उन्नीस सौ उनतालीस में छपा। एलियट गंभीर, दार्शनिक कविताओं के लिए जाने जाते हैं, पर इस संग्रह में उन्होंने बच्चों के लिए मज़ेदार कविताएँ लिखीं। बाद में इसी संग्रह पर प्रसिद्ध संगीत-नाटक कैट्स बना। इसलिए जब आप यह कविता पढ़ें, तो गंभीरता की जगह हास्य और खेल के मूड में पढ़ें, पर उसके पीछे की चतुर कल्पना को भी देखें।"),
C("✍️","टी एस एलियट का परिचय",["जन्म अमेरिका में, बसे इंग्लैंड में","आधुनिक कविता के प्रमुख कवि","द वेस्ट लैंड प्रसिद्ध रचना","1948 में नोबेल पुरस्कार"],"कवि टी एस एलियट का पूरा नाम थॉमस स्टर्न्स एलियट है। उनका जन्म अमेरिका में हुआ, पर वे बाद में इंग्लैंड में बस गए। उन्हें बीसवीं सदी के आधुनिक अंग्रेज़ी कवियों में सबसे प्रमुख माना जाता है। उनकी प्रसिद्ध रचनाओं में द वेस्ट लैंड और द लव सॉन्ग ऑफ़ जे अल्फ़्रेड प्रूफ़्रॉक शामिल हैं। उन्नीस सौ अड़तालीस में उन्हें साहित्य का नोबेल पुरस्कार मिला। परीक्षा के लिए उनका जन्म-देश, बसा हुआ देश और नोबेल पुरस्कार का वर्ष अवश्य याद रखिए।"),
C("🕵️","मैकेविटी: रहस्यमय अपराधी",["हर अपराध का सरगना","कभी मौक़े पर नहीं मिलता","सबूत नहीं छोड़ता","जैसे मिनट की बारीक चाल"],"कविता का नायक मैकेविटी एक बिल्ली है, जिसे अपराध जगत का सरगना बताया गया है। उसे हर चोरी, हर नुक़सान के पीछे माना जाता है, पर जब पुलिस पहुँचती है, तो वह कभी मौक़े पर नहीं मिलता। कवि बड़े हास्य से बताते हैं कि वह जगह पर होता ही नहीं, इसलिए सबूत भी नहीं बचता। उसकी चालाकी को इतना बढ़ा-चढ़ाकर दिखाया गया है कि पाठक हँसने लगता है। यह रहस्य और हास्य का मज़ेदार मेल है, जैसे जासूसी कहानी का मज़ाक उड़ाया जा रहा हो।"),
C("👮","पुलिस की बेबसी",["स्कॉटलैंड यार्ड भी असमर्थ","सब जाँचें विफल","क़ानून के जाल से बाहर","व्यवस्था पर हल्का व्यंग्य"],"कविता में लंदन की प्रसिद्ध पुलिस स्कॉटलैंड यार्ड और फ़्लाइंग स्क्वाड भी मैकेविटी को पकड़ने में बेबस दिखती है। कवि हँसी में कहते हैं कि इतनी बड़ी जाँच एजेंसियाँ भी इस बिल्ली के सामने हार जाती हैं। यह हास्य के साथ-साथ व्यंग्य भी है कि अगर अपराधी बहुत चतुर हो और सबूत न छोड़े, तो व्यवस्था की कमज़ोरी उजागर हो जाती है। यह हल्का-फुल्का व्यंग्य बच्चों को मज़ा देता है और बड़ों को सोचने के लिए कुछ देता है।"),
C("🎭","बिल्ली का मानवीकरण",["बिल्ली को इंसान की तरह दिखाना","अपराधी जैसे गुण","इंसानी स्वभाव पर कटाक्ष","जीव-जंतुओं से सीख"],"कविता में बिल्ली को इंसान की तरह दिखाया गया है। उसे अपराधी का स्वभाव, चतुराई और बच निकलने की कला दी गई है। इसे मानवीकरण कहते हैं। इसके माध्यम से कवि असल में इंसानों के स्वभाव पर कटाक्ष करते हैं, कि समाज में भी कुछ लोग ऐसे होते हैं जो गड़बड़ करके भी बच निकलते हैं। साहित्य में जानवरों का इंसानी चरित्र के रूप में प्रयोग बहुत पुराना है, जैसे हमारे पंचतंत्र में। फ़र्क़ बस इतना है कि यहाँ शैली बहुत आधुनिक और चटपटी है।"),
C("🎼","लय, तुक और ध्वनि",["तेज़ लय","तुकांत पंक्तियाँ","मज़ेदार शब्द-खेल","पढ़ने में सुखद"],"इस कविता की सबसे बड़ी ख़ासियत उसकी तेज़ लय और तुकबंदी है। पंक्तियाँ ऐसे चलती हैं जैसे ताल पर बजते ढोल। तुकांत शब्द जैसे बार-बार आते हैं, वे कविता को याद रखने में आसान बनाते हैं। कवि मज़ेदार शब्दों और ध्वनियों से खेलते हैं। ज़ोर से पढ़ने पर इसकी गति और मज़ा और बढ़ जाता है। परीक्षा में काव्य सौंदर्य लिखते समय लय, तुक और मानवीकरण के साथ हास्य और व्यंग्य का उल्लेख भी कीजिए, क्योंकि यही इसकी पहचान हैं।"),
C("😂","हास्य और व्यंग्य का फ़र्क़",["हास्य: सिर्फ़ हँसाना","व्यंग्य: हँसाकर सोचने को मजबूर करना","यहाँ दोनों मिले","अतिशयोक्ति का प्रयोग"],"हास्य और व्यंग्य में एक छोटा सा अंतर है। हास्य का उद्देश्य हँसाना है, जबकि व्यंग्य हँसी के साथ किसी कमी की ओर इशारा करता है। इस कविता में दोनों हैं। हास्य बिल्ली की हरकतों में है और व्यंग्य पुलिस की असफलता और समाज की व्यवस्था पर। साथ में अतिशयोक्ति भी है, यानी बात को बढ़ा-चढ़ाकर कहना, जैसे बिल्ली को पूरी दुनिया का सबसे बड़ा अपराधी बताना। परीक्षा में इन तीनों के उदाहरण साथ-साथ लिखिए।"),
C("📝","शब्दार्थ दोहराइए",["मिस्ट्री यानी रहस्य","क्रिमिनल यानी अपराधी","एविडेंस यानी सबूत","डिटेक्टिव यानी जासूस"],"आइए शब्द दोहराएँ। मिस्ट्री यानी रहस्य, क्रिमिनल यानी अपराधी, एविडेंस यानी सबूत, डिटेक्टिव यानी जासूस और एलिबाई यानी घटना के समय किसी दूसरी जगह होने का बहाना। साथ में पुलिस, क्राइम और कनिंग यानी चालाक भी याद कर लीजिए। अब हर शब्द से एक वाक्य बनाइए। जैसे द पुलिस कुड नॉट फ़ाइंड एनी एविडेंस, यानी पुलिस को कोई सबूत नहीं मिला। और ही इज़ अ कनिंग क्रिमिनल, यानी वह चालाक अपराधी है।"),
C("🧩","व्याकरण: निगेटिव और जनरल कथन",["नेवर, नो, नॉट","दैट्स नॉट देयर, ही इज़ नेवर देयर","सामान्य सत्य के लिए प्रेज़ेंट सिंपल","नकारात्मक वाक्य बनाना"],"कविता में बार-बार नकारात्मक वाक्य हैं, कि वह वहाँ नहीं मिलता और उसके ख़िलाफ़ सबूत नहीं मिलता। इसके लिए नेवर, नॉट और नो का प्रयोग होता है। जैसे ही इज़ नेवर एट द सीन, यानी वह कभी घटनास्थल पर नहीं होता। यहाँ प्रेज़ेंट सिंपल का प्रयोग है, जो आदतों और सामान्य सत्य के लिए होता है। नेवर का स्थान सहायक क्रिया के बाद या मुख्य क्रिया से पहले होता है। अपने आसपास के किसी चतुर या शरारती व्यक्ति पर चार नकारात्मक वाक्य बनाइए।"),
C("🐾","बिल्लियाँ और संस्कृति",["बिल्ली का रहस्यमय स्वभाव","कहावतें: बिल्ली के भाग से छींका टूटा","बिहार में बिल्ली की लोक-कथाएँ","बच्चों की कहानियों में बिल्ली"],"बिल्ली का स्वभाव ही कुछ रहस्यमय माना जाता है, इसलिए वह दुनिया भर के साहित्य और लोककथाओं में आती है। हमारे यहाँ बिल्ली के भाग से छींका टूटा जैसी कहावतें हैं और बच्चों की बहुत सी कहानियों में बिल्ली चालाक पात्र की तरह आती है, जैसे दो बिल्लियों और बंदर की कहानी। बिहार के गाँवों में भी बिल्ली से जुड़ी दिलचस्प लोककथाएँ सुनाई जाती हैं। इस तरह एलियट की कविता एक अंतर्राष्ट्रीय परंपरा से जुड़ती है, जहाँ जानवरों के बहाने मनुष्य के स्वभाव पर हँसा जाता है।"),
C("📌","कविता का सार",["मैकेविटी: रहस्यमय अपराधी बिल्ली","हर अपराध का सरगना, पर सबूत नहीं","पुलिस बेबस","हास्य और व्यंग्य की कविता"],"अब कविता का सार दोहरा लें। टी एस एलियट की मैकेविटी द मिस्ट्री कैट में एक रहस्यमय बिल्ली है, जिसे हर अपराध का सरगना माना जाता है, पर वह कभी मौक़े पर नहीं मिलती और उसके ख़िलाफ़ कोई सबूत नहीं मिलता। पुलिस भी उसके सामने बेबस है। कविता में हास्य, व्यंग्य, तुकबंदी और मानवीकरण है। संदेश है कि चतुर अपराधी बच निकलते हैं, इसलिए क़ानून और व्यवस्था को सतर्क रहना चाहिए। इसे अपने शब्दों में पाँच वाक्यों में लिखिए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवि और संग्रह","मैकेविटी का चरित्र","कविता का हास्य कहाँ है","काव्य-सौंदर्य"],"परीक्षा के प्रश्न देखिए। पहला, कवि कौन हैं और कविता किस संग्रह से है? उत्तर, टी एस एलियट, ओल्ड पोसम्स बुक ऑफ़ प्रैक्टिकल कैट्स से। दूसरा, मैकेविटी का चरित्र बताइए। उत्तर, चतुर, रहस्यमय, सरगना, जो सबूत नहीं छोड़ता। तीसरा, हास्य कहाँ है? उत्तर, बिल्ली को अपराधी की तरह और पुलिस को बेबस दिखाने में। चौथा, काव्य-सौंदर्य? उत्तर, लय, तुक, मानवीकरण, हास्य और व्यंग्य। पूरे वाक्य में उत्तर लिखिए।"),
Q("क्या चालाक अपराधी का बच निकलना समाज के लिए ठीक है? कविता के आधार पर अपना मत दीजिए।","नहीं, कविता हास्य में बताती है कि कमज़ोर व्यवस्था अपराधी को बचा लेती है, इसलिए क़ानून मज़बूत और सतर्क होना चाहिए।","एक सोचने वाला प्रश्न। क्या चालाक अपराधी का बच निकलना समाज के लिए ठीक है? कविता के आधार पर सोचिए। ... नहीं, कविता हास्य में यह बताती है कि कमज़ोर व्यवस्था अपराधी को बचा लेती है। इसलिए क़ानून मज़बूत और सतर्क होना चाहिए, और हमें भी सच के साथ खड़ा रहना चाहिए।"),
],7)
